INSERT INTO plan_policy_features(policy_version_id,page_key,feature_key,enabled,upgrade_message) SELECT pv.id,'analytics','advanced_analytics',CASE WHEN sp.tier_key='pro' THEN 1 ELSE 0 END,'Upgrade to Pro to use advanced performance analysis.' FROM plan_policy_versions pv JOIN subscription_plans sp ON sp.id=pv.plan_id WHERE sp.tier_key IN ('free','basic','pro') ON CONFLICT(policy_version_id,feature_key) DO NOTHING;
