-- Add completed services to existing policy contracts without changing payment terms.
PRAGMA foreign_keys=ON;
UPDATE plan_policy_features SET storage_limit_bytes=MAX(COALESCE(storage_limit_bytes,0),262144000),quantity_limit=NULL WHERE feature_key IN ('resources.storage','resources_storage') AND policy_version_id IN (SELECT pv.id FROM plan_policy_versions pv JOIN subscription_plans sp ON sp.id=pv.plan_id WHERE sp.tier_key='free');
UPDATE plan_entitlements SET limit_value=MAX(COALESCE(limit_value,0),250),limit_unit='megabytes' WHERE feature_key IN ('resources.storage','resources_storage') AND plan_id IN (SELECT id FROM subscription_plans WHERE tier_key='free');
